"""Explain scoped local locks and per-CPU read/write semaphores."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1413': ('열쇠를 빌릴 때 나갈 때 돌려줄 일을 함께 적어 두면 중간에 돌아가더라도 반납을 잊지 않기 쉽습니다. guard는 잠금의 획득과 해제를 이런 한 쌍으로 연결합니다.', '범위가 끝날 때 자동 해제하는 guard와 저장할 IRQ 상태를 이해합니다.', 'irqsave guard 안에 lock과 flags 두 칸을 그리세요. 획득 때 저장한 flags에서 같은 guard의 irqrestore로 화살표를 이으세요.', ['scope는 C 코드에서 지역 변수가 살아 있는 범위입니다. guard는 그 범위에 들어와 잠금을 얻고, 해당 지역 변수의 정리 시점에 맞는 해제를 연결하는 방식입니다. 올바른 사용은 획득과 해제가 한 번씩 짝을 이루는 것입니다.', 'local_lock.h의 DEFINE_GUARD는 기본 local_lock과 local_unlock을 연결합니다. IRQ용은 local_lock_irq와 local_unlock_irq, nested BH용도 같은 종류의 획득·해제를 연결합니다. 필요한 문맥 조건까지 없어지는 것은 아닙니다.', 'irqsave는 잠금 주소만 기억해서는 부족합니다. 이전 인터럽트 상태도 대응 해제에 필요합니다. DEFINE_LOCK_GUARD_1은 unsigned long flags라는 필드를 더하여 그 정보를 함께 보관합니다.', '획득 식은 _T->lock과 _T->flags를 사용하고 해제 식도 같은 두 필드를 사용합니다. ->는 포인터가 가리키는 구조체 안의 항목에 접근하는 C 문법입니다. 같은 guard가 얻을 때 저장한 상태를 풀 때 다시 전달하는 것입니다.', '자동 정리가 맡은 잠금을 중간에 수동으로 풀고 그대로 범위를 끝내면 두 번 해제할 수 있습니다. 자동 해제 범위와 변수 수명을 분명히 하고, 다른 guard의 flags를 섞지 마세요. RT에서는 flags의 내부 의미가 일반 구성과 다르다는 앞 수업의 조건도 그대로 적용됩니다.', '매크로 연결을 읽어 어떤 해제가 등록되는지 확인하는 것과, 실제로 생성된 정리 코드를 실행해 보는 것은 다른 검증입니다. 생성 매크로를 빈 것으로 바꾼 시험은 정리 함수 실행을 증명하지 못합니다. 설명이나 검사 결과를 읽을 때 무엇을 실제 실행했는지도 구별하세요.'], [('irqsave guard는 잠금 외에 무엇을 추가로 보관할까요?', ['언제나 비트맵 원소 수예요', 'unsigned long 타입의 flags예요'], '획득할 때 저장한 상태를 같은 guard의 irqrestore에 넘겨야 하므로 flags 필드가 있습니다. 비트맵 길이와는 관계없습니다.'), ('guard 생성 매크로를 빈 것으로 바꾼 시험이 자동 정리 코드 실행까지 증명할까요?', ['아니요. 연결을 읽은 것과 생성 코드를 실행한 것은 달라요', '네. 모든 자동 해제 함수가 실행됐다고 볼 수 있어요'], '빈 매크로는 실제 guard 생성과 정리를 수행하지 않습니다. 원문의 연결은 설명할 수 있어도 그 시험만으로 정리 함수가 실행됐다고 말할 수 없습니다.')]), 'os1414': ('여러 교실에서 같은 자료를 읽는 사람 수는 교실마다 적되, 내용을 고치는 시간에는 새 독자가 들어오는 문을 막습니다. 인원표와 출입문 표시는 역할이 다릅니다.', 'CPU별 읽기 카운터, 쓰기 차단, 빠른 경로 전환의 역할을 구별합니다.', 'read_count=읽기 수 기록, block=쓰기 독점과 새 독자 차단, rss=빠른 읽기 경로 전환이라고 세 칸을 적으세요. block=0에서 rss가 아직 전환 중일 수 있다고 표시하세요.', ['percpu_rw_semaphore는 읽기는 자주 하고 쓰기는 드문 자료를 보호하는 구조입니다. 여러 독자가 함께 읽을 수 있지만 쓰는 쪽은 기존 독자들이 끝나기를 기다려야 합니다. per-CPU는 CPU마다 별도 기록을 둔다는 뜻입니다.', 'read_count는 CPU별 unsigned int 카운터를 가리킵니다. 읽기 획득과 반납이 이 카운터들에 반영되고, 쓰는 쪽은 전체 합으로 남은 독자를 판단합니다. 모든 독자가 하나의 공용 숫자를 계속 고치는 부담을 줄이려는 구조입니다.', 'block은 원자적으로 다루는 차단 표시입니다. writer가 이 표시를 차지하여 다른 writer와 배타적으로 동작하고 새 reader가 들어오지 못하게 합니다. 카운터의 주소나 전체 독자 수와는 다른 필드입니다.', 'rss는 RCU-sync 상태입니다. 독자가 빠른 경로를 써도 되는지와 쓰기 전후의 전환을 관리합니다. block이 0이라고 rss도 곧바로 idle인 것은 아닙니다. 두 정보가 같은 숫자 하나를 중복 저장하는 것이 아닙니다.', 'writer의 rcuwait는 활동 중인 독자들이 끝나기를 기다리는 쓰기 쪽을 위한 대기 정보입니다. waiters는 진입을 기다리는 읽기·쓰기 작업의 대기열입니다. 디버그 구성의 dep_map은 잠금 관계 분석 기록입니다.', '쓰기 해제는 block을 먼저 0으로 공개하고 대기자를 깨운 뒤 RCU-sync 종료를 진행합니다. 빠른 읽기는 관련 유예 기간을 거쳐 다시 가능해집니다. 바로 빠른 길로 보내지 않아 새 독자가 쓰기 결과를 올바른 순서로 보게 하는 과정과 연결됩니다.'], [('writer끼리의 배제와 새 reader 차단에 사용하는 필드는 무엇일까요?', ['read_count 포인터 주소예요', 'block이에요'], 'writer가 block을 차지하고 reader가 그 상태를 검사합니다. CPU별 카운터 합은 기존 읽기 보유를 세는 다른 역할입니다.'), ('block이 0이면 빠른 읽기 경로도 언제나 즉시 idle일까요?', ['아니요. RCU-sync의 복귀는 별도로 진행돼요', '네. 두 필드는 언제나 같은 상태예요'], '쓰기 해제에서 block을 먼저 0으로 만들지만 빠른 경로는 RCU-sync 전환을 거칩니다. 문을 여는 표시와 빠른 길의 사용 가능 여부를 구별해야 합니다.')]), 'os1415': ('교실별 인원표를 쓰려면 먼저 종이를 준비하고 대기 명단도 초기화해야 합니다. 종이를 구하지 못했는데 준비 완료라고 하면 안 됩니다.', '초기화 성공·실패와 정리 후 NULL의 의미를 이해합니다.', '할당 실패 → -ENOMEM, 성공 → 나머지 초기화 → 0을 쓰세요. 정리 순서는 RCU-sync 정리 → CPU별 공간 반납 → 포인터 NULL입니다.', ['__percpu_init_rwsem은 먼저 alloc_percpu(int)로 CPU별 카운터 공간을 확보합니다. 반환 주소를 read_count에 저장합니다. per-CPU 공간은 CPU마다 대응 원소가 있는 저장 공간입니다.', '공간 확보가 실패하여 포인터가 없으면 -ENOMEM을 반환합니다. 메모리를 구하지 못했다는 음수 오류 표시입니다. 성공 0과 구별하고, 초기화 실패한 구조를 독자나 writer에게 공개하면 안 됩니다.', '성공하면 rcu_sync_init, rcuwait_init, init_waitqueue_head로 전환 상태와 두 대기 구조를 준비합니다. block은 0으로 만듭니다. 디버그 설정이 켜졌다면 분석 기록도 준비한 뒤 성공 0을 반환합니다.', 'percpu_free_rwsem은 read_count가 NULL이면 바로 돌아갑니다. 원문은 0으로 초기화한 객체의 오류 정리 경로를 지원하려는 이유를 설명합니다. 임의의 쓰레기 주소가 든 미초기화 객체에도 안전하다는 뜻은 아닙니다.', '포인터가 있으면 먼저 rcu_sync_dtor를 호출하고 free_percpu로 공간을 반납한 다음 read_count=NULL로 만듭니다. NULL은 더 이상 사용할 카운터 주소가 없다는 표시입니다. 옛 주소를 계속 유효한 것으로 쓰는 실수를 드러내는 데 도움이 됩니다.', '포인터를 NULL로 바꿔도 다른 코드가 보관한 옛 주소까지 지워지지는 않습니다. 사용 중인 독자·writer·대기자가 없도록 수명을 정리한 뒤 해제해야 합니다. 이 함수가 모든 활성 사용자를 자동으로 종료시킨다고 가정하지 마세요.'], [('CPU별 카운터 할당에 실패하면 어떤 값을 반환할까요?', ['성공 0과 NULL 카운터를 반환해요', '-ENOMEM을 반환해요'], '포인터가 없으면 즉시 음수 오류로 돌아갑니다. 나머지 준비까지 성공한 경우에만 0을 반환하므로 사용 전 결과 확인이 필요합니다.'), ('정상 정리 후 read_count에는 무엇을 저장할까요?', ['NULL을 저장해요', '해제 전 주소를 계속 남겨요'], 'free_percpu 뒤에 NULL을 대입합니다. 더 이상 사용할 주소가 없음을 표시하지만 다른 사용자의 수명 문제까지 자동 해결하는 것은 아닙니다.')]), 'os1416': ('도서관 입구에서 입장 인원만 짧게 기록한 뒤 책은 안에서 읽습니다. 입장 기록을 보호하는 짧은 시간과 실제 독서 시간은 다릅니다.', '빠른 읽기 획득의 짧은 선점 제어와 실제 읽기 보유 시간을 구별합니다.', 'down_read 시작 → 선점 금지 → 현재 CPU 인원 증가 → 선점 복구 → 자료 읽기 → up_read로 반납 순서를 그리세요. 인원 증가를 보호하는 구간과 독서 구간을 따로 표시하세요.', ['percpu_down_read는 읽기 사용권을 얻는 함수입니다. might_sleep은 잠들 수 있는 호출 문맥인지 점검하는 표시이며, 이 줄이 반드시 잠을 재운다는 뜻은 아닙니다. 대기할 수 있는 API의 호출 조건을 지켜야 합니다.', '분석 도구에 읽기 획득을 알린 뒤 preempt_disable로 잠깐 선점을 금지합니다. 현재 CPU의 기록을 선택하고 경로를 결정하는 구간을 보호합니다. 선점은 다른 작업으로 CPU 실행이 바뀌는 것입니다.', 'rcu_sync_is_idle(&sem->rss)가 참이면 this_cpu_inc로 현재 CPU의 read_count를 하나 늘립니다. 모든 독자가 하나의 공용 word에 CAS를 반복하는 방식이 아닙니다. 각 CPU 기록을 사용해 공유 메모리 경합을 줄입니다.', 'rss가 idle이 아니면 __percpu_down_read(sem,false)라는 별도 경로로 갑니다. 쓰기 쪽과의 진입 조정, 필요한 메모리 순서 및 대기 처리는 그 경로에 있습니다. 읽기용 빠른 조건이 아니라고 무조건 획득 실패를 반환하는 함수는 아닙니다.', 'wrapper는 마지막에 preempt_enable로 이번 금지를 되돌리고 돌아갑니다. 그 뒤에도 읽기 사용권은 살아 있고 실제 자료 읽기가 이어집니다. 종료할 때 percpu_up_read를 짝지어야 합니다. down_read부터 up_read까지 전부 이번 선점 금지가 유지되는 것은 아닙니다.', '짧은 선점 제어와 RCU-sync의 쓰기 전환은 writer가 빠른 경로의 독자 등록을 놓치지 않게 맞물립니다. writer가 전환 뒤 카운터를 확인할 때 이 등록이 반영되도록 하는 규칙입니다. 카운터 증가만 떼어 내어 아무 동기화 없이 써도 된다고 해석하면 안 됩니다.'], [('down_read가 반환한 뒤에도 이번 preempt_disable을 up_read까지 유지할까요?', ['네. 전체 읽기 시간 내내 이번 금지가 남아요', '아니요. wrapper가 반환 전에 복구해요'], '끝의 preempt_enable이 이번 금지를 되돌립니다. 읽기 사용권의 보유 시간과 카운터 등록을 보호하는 짧은 구간은 다릅니다.'), ('빠른 읽기는 모든 독자가 하나의 공용 카운터를 원자적으로 고칠까요?', ['아니요. 현재 CPU의 카운터를 늘려요', '네. 항상 하나의 공유 word에 CAS를 해요'], 'this_cpu_inc가 현재 CPU 기록을 바꿉니다. writer가 나중에 전체 합을 확인하는 설계이므로 공용 숫자 하나에 매번 경쟁하는 것과 다릅니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_349.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
